/*!
 * PLACEHOLDER htmx-compatible subset — REPLACE with the official vendored
 * htmx.min.js (1.9.x) at packaging time. Patchline's build sandbox has no
 * network access, so the real htmx could not be vendored this round.
 *
 * This subset implements ONLY what Patchline templates use:
 *   hx-get + hx-trigger="every Ns" + hx-swap="innerHTML" (polling regions).
 * All Patchline pages are fully functional without JS (plain forms + links);
 * this file only upgrades the scan-console polling experience. CSRF: mutating
 * fetch calls made by this shim copy the X-CSRF-Token header from any hidden
 * csrf_token field on the page.
 */
(function () {
  "use strict";
  function swapInner(el, html) { el.innerHTML = html; el.setAttribute("aria-busy", "false"); }
  function poll(el) {
    var url = el.getAttribute("hx-get");
    if (!url) { return; }
    var trigger = el.getAttribute("hx-trigger") || "";
    var m = trigger.match(/every\s+(\d+(?:\.\d+)?)(m?s)/);
    if (!m) { return; }
    var interval = parseFloat(m[1]) * (m[2] === "ms" ? 1 : 1000);
    setInterval(function () {
      el.setAttribute("aria-busy", "true");
      fetch(url, { headers: { "X-Requested-With": "htmx-subset" }, credentials: "same-origin" })
        .then(function (r) { return r.ok ? r.text() : Promise.reject(r.status); })
        .then(function (html) { swapInner(el, html); })
        .catch(function () { el.setAttribute("aria-busy", "false"); });
    }, interval);
  }
  function boot() {
    document.querySelectorAll("[hx-get]").forEach(poll);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else { boot(); }
})();
